const crypto = require('crypto');
const key = crypto.randomBytes(32);                 // clave al azar, distinta en cada corrida
const nonce = Buffer.alloc(12, 7);                  // el mismo nonce, por error, para los dos mensajes
const cifrar = (m) => { const c = crypto.createCipheriv('aes-256-gcm', key, nonce); return Buffer.concat([c.update(m), c.final()]); };
const m1 = Buffer.from('Cobrar 500 a la cuenta 1234 hoy');
const m2 = Buffer.from('Cobrar 900 a la cuenta 9876 ya!');
const c1 = cifrar(m1), c2 = cifrar(m2);
const xor = (a, b) => Buffer.from(a.map((x, i) => x ^ b[i]));
console.log('c1 XOR c2     :', xor(c1, c2).toString('hex'));
console.log('m1 XOR m2     :', xor(m1, m2).toString('hex'));
console.log('¿son iguales? :', xor(c1, c2).equals(xor(m1, m2)));
console.log('conociendo m1 :', xor(xor(c1, c2), m1).toString());

// RSA de JUGUETE: números chicos para ver la idea. Jamás se usa así.
const potMod = (b, e, m) => { let r = 1n; b %= m; while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; } return r; };
